/* Shared UI duration; database is authoritative for every reservation and change. */
function classMinutes(tid,subject,teachers){const name=(teachers||((typeof db!=='undefined'&&db.teachers)||[])).find(t=>t.id===tid)?.name;return name==='حاجیان'&&['سلفژ','صداسازی','سلفژوصداسازی'].includes(String(subject||'').replace(/[\s\u200c]/g,''))?30:20}
function durationTimeOptions(tid,subject,teachers){const step=classMinutes(tid,subject,teachers)===30?10:20;return Array.from({length:Math.floor(((step===10?750:760))/step)+1},(_,i)=>{const m=600+i*step,t=String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');return [t,t]})}
function minutesAt(t){return Number(t.slice(0,2))*60+Number(t.slice(3,5))}
function timeOverlaps(a,ad,b,bd){return minutesAt(a)<minutesAt(b)+bd&&minutesAt(b)<minutesAt(a)+ad}
// Update staff forms on course selection; avoid resizing or moving a focused dialog.
document.addEventListener('change',e=>{const f=e.target.closest('form');if(!f||!['teacher_id','subject'].includes(e.target.name))return;syncStaffDuration(f)});
function syncStaffDuration(f){if(!f?.elements?.teacher_id||!f.elements.subject||!f.elements.class_time||f.querySelector('#registration-course-list'))return;const t=f.elements.class_time,tid=f.elements.teacher_id.value,sub=f.elements.subject.value,old=t.value,n=classMinutes(tid,sub);if(t.tagName==='SELECT'){t.replaceChildren(...durationTimeOptions(tid,sub).map(([v])=>Object.assign(document.createElement('option'),{value:v,textContent:v})));if([...t.options].some(o=>o.value===old))t.value=old;}else t.step=n===30?'600':'1200';let hint=t.parentElement.querySelector('.duration-hint');if(!hint){hint=document.createElement('small');hint.className='duration-hint';t.parentElement.append(hint)}hint.textContent='مدت این کلاس: '+n.toLocaleString('fa-IR')+' دقیقه';}
new MutationObserver(()=>{const f=document.querySelector('#form');if(f&&!f.dataset.durationSynced&&document.querySelector('#modal[open],dialog[open]')){f.dataset.durationSynced='1';syncStaffDuration(f)}else if(f&&!document.querySelector('dialog[open]'))delete f.dataset.durationSynced;}).observe(document.documentElement,{subtree:true,attributes:true,attributeFilter:['open']});
